const QUERY_NAMES = {
  UsageEvent: "UsageEvents",
  UserHourly: "UserHourlys",
  TeamHourly: "TeamHourlys",
  IngestKey: "IngestKeys",
  ModelPrice: "ModelPrices",
  RollupState: "RollupStates",
  LinkedAccount: "LinkedAccounts",
  LinkChallenge: "LinkChallenges"
