    if (!row) continue;
    if (row.provider && event.provider && row.provider !== event.provider) continue;
    const from = toTime(row.effectiveFrom);
    if (isNaN(from) || isNaN(at) || from > at) continue;
    const match = matchPriceRow(row, model);
